/* eslint-disable max-len */

'use strict';

// MODULES //

var passfb5 = require( './passfb5.js' );
var passfb = require( './passfb.js' );
var passf4 = require( './passf4.js' );
var passf2 = require( './passf2.js' );
var passf3 = require( './passf3.js' );


// MAIN //

/**
* Performs the complex forward Fast Fourier Transform.
*
* @private
* @param {number} n - length of the sequence to transform
* @param {Float64Array} c - input array containing sequence to be transformed
* @param {Float64Array} ch - working array for intermediate results
* @param {Float64Array} wa - array of twiddle factors
* @param {Int32Array} ifac - array containing factorization information
* @returns {void}
*/
function cfftf1( n, c, ch, wa, ifac ) {
	var idl1;
	var idot;
	var nac;
	var ido;
	var ix4;
	var ix3;
	var ix2;
	var nf;
	var na;
	var l2;
	var l1;
	var iw;
	var ip;
	var k1;
	var i;

	// Function Body:
	nf = ifac[ 1 ];
	na = 0;
	l1 = 1;
	iw = 0;
	for ( k1 = 1; k1 <= nf; k1++ ) {
		ip = ifac[ k1 + 1 ];
		l2 = ip * l1;
		ido = n / l2;
		idot = ido + ido;
		idl1 = idot * l1;
		switch ( ip ) {
		case 4:
			ix2 = iw + idot;
			ix3 = ix2 + idot;
			passf4( idot, l1, ( na ) ? ch : c, ( na ) ? c : ch, wa[ iw ], wa[ ix2 ], wa[ ix3 ] );
			na = 1 - na;
			break;
		case 2:
			passf2( idot, l1, ( na ) ? ch : c, ( na ) ? c : ch, wa[ iw ] );
			na = 1 - na;
			break;
		case 3:
			ix2 = iw + idot;
			passf3( idot, l1, ( na ) ? ch : c, ( na ) ? c : ch, wa[ iw ], wa[ ix2 ] );
			na = 1 - na;
			break;
		case 5:
			ix2 = iw + idot;
			ix3 = ix2 + idot;
			ix4 = ix3 + idot;
			passfb5( idot, l1, ( na ) ? ch : c, ( na ) ? c : ch, wa[ iw ], wa[ ix2 ], wa[ ix3 ], wa[ ix4 ], -1 );
			na = 1 - na;
			break;
		default:
			if ( na === 0 ) {
				passfb( nac, idot, ip, l1, idl1, c, c, c, ch, ch, wa[ iw ], -1 );
			} else {
				passfb( nac, idot, ip, l1, idl1, ch, ch, ch, c, c, wa[ iw ], -1 );
			}
			if ( nac !== 0 ) {
				na = 1 - na;
			}
			break;
		}
		l1 = l2;
		iw += ( ip - 1 ) * idot;
	}
	if ( na === 0 ) {
		return;
	}
	for ( i = 0; i < ( 2 * n ); i++ ) {
		c[ i ] = ch[ i ];
	}
}


// EXPORTS //

module.exports = cfftf1;
